import { validate,statusOf,totals,safePath,assertBackup } from './core.js';
import {sha256,csv} from './integrity.js';
import { issueLabels } from './issues.js';
import { getFile,replaceWorkspace } from './storage.js';
export function download(data,name,type='application/octet-stream'){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export async function workbook(state,docs){
 const {default:ExcelJS}=await import('exceljs');const wb=new ExcelJS.Workbook();wb.creator='InvoiceGuard';wb.created=new Date();
 const invoice=wb.addWorksheet('Invoices');const headers=['File','Company','Batch','Claimant','Batch status','Document type','Country','Currency','Merchant','Buyer','Buyer tax ID','Seller tax ID','Invoice code','Invoice number','Date','Category','Subtotal','Tax','Tip','Discount','Total','Status','Reviewed','Notes','Record ID','Original SHA-256','Archive path'];invoice.addRow(headers);
 const errorSheet=wb.addWorksheet('Issues');errorSheet.addRow(['File','Company','Batch','Severity','Code','Issue (English)','Issue (中文)','Match / detail']);
 for(const d of docs){const c=state.companies.find(x=>x.id===d.companyId),b=state.batches.find(x=>x.id===d.batchId),issues=validate(d,c,state.documents);invoice.addRow([d.filename,c?.name,b?.name,b?.employee,b?.status,d.documentType,d.country,d.currency,d.vendor,d.buyer,d.buyerTaxId,d.sellerTaxId,d.invoiceCode,d.invoiceNumber,d.date,d.category,d.subtotal,d.tax,d.tip,d.discount,d.total,statusOf(d,issues),d.reviewed?'Yes':'No',d.notes,d.id,d.hash,archivePath(state,d)]);for(const i of issues)errorSheet.addRow([d.filename,c?.name,b?.name,i.severity,i.code,...(issueLabels[i.code]||[i.code,i.code]),i.detail]);}
 const summary=wb.addWorksheet('Summary');summary.addRow(['Company','Currency','Included documents','Included total','Ready total']);
 for(const c of state.companies)for(const currency of ['CNY','USD']){const selected=docs.filter(d=>d.companyId===c.id&&d.currency===currency&&!d.excluded); if(selected.length)summary.addRow([c.name,currency,selected.length,totals(selected)[currency],totals(selected.filter(d=>statusOf(d,validate(d,c,state.documents))==='ready'))[currency]]);}
 summary.addRow([]);summary.addRow(['Currencies are not converted. Included totals may contain unresolved issues.']);summary.addRow(['Tax ID checks do not verify registration, deductibility, or invoice authenticity.']);
 for(const s of wb.worksheets){s.views=[{state:'frozen',ySplit:1}];s.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};s.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF16775B'}};s.getRow(1).height=25;s.columns.forEach((c,i)=>{c.width=i===0?30:22;});if(s===invoice){for(let col=17;col<=21;col++){s.getColumn(col).numFmt='#,##0.00';}}s.autoFilter={from:{row:1,column:1},to:{row:Math.max(1,s.rowCount),column:s.columnCount}};}
 return wb.xlsx.writeBuffer();
}
export async function exportExcel(state,docs){download(await workbook(state,docs),'InvoiceGuard-summary.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}

export function archivePath(state,d){const c=state.companies.find(x=>x.id===d.companyId),b=state.batches.find(x=>x.id===d.batchId);return [safePath(c?.name),safePath(b?.name),safePath(d.category),safePath(statusOf(d,validate(d,c,state.documents))),safePath(d.id)+'_'+safePath(d.filename)].join('/');}
function issueRows(state,docs){const rows=[['File','Company','Batch','Severity','Code','Issue','问题','Details','Record ID','Original SHA-256','Archive path']];for(const d of docs){const c=state.companies.find(x=>x.id===d.companyId);for(const i of validate(d,c,state.documents))rows.push([d.filename,c?.name,d.batchId,i.severity,i.code,...(issueLabels[i.code]||[i.code,i.code]),i.detail,d.id,d.hash,archivePath(state,d)]);}return rows;}
function summaryRows(state,docs){return [['File','Country','Currency','Vendor','Buyer','Buyer tax ID','Seller tax ID','Invoice number','Date','Category','Subtotal','Tax','Tip','Discount','Total','Status','Record ID','Original SHA-256','Archive path'],...docs.map(d=>[d.filename,d.country,d.currency,d.vendor,d.buyer,d.buyerTaxId,d.sellerTaxId,d.invoiceNumber,d.date,d.category,d.subtotal,d.tax,d.tip,d.discount,d.total,statusOf(d,validate(d,state.companies.find(c=>c.id===d.companyId),state.documents)),d.id,d.hash,archivePath(state,d)])];}
export async function exportCSV(state,docs){download(csv(summaryRows(state,docs)),'InvoiceGuard-summary.csv','text/csv;charset=utf-8');}
export async function exportErrors(state,docs){download(csv(issueRows(state,docs)),'InvoiceGuard-issues.csv','text/csv;charset=utf-8');}
async function original(d){const file=await getFile(d.id);if(!file)throw new Error('Original file missing: '+d.filename+'. Restore a complete backup before exporting.');const data=new Uint8Array(await file.arrayBuffer()),hash=await sha256(data);if(d.hash&&d.hash!==hash)throw new Error('Original checksum mismatch: '+d.filename);return {data,hash};}
export async function exportArchive(state,docs){const {zipSync,strToU8}=await import('fflate');const files={'summary.xlsx':new Uint8Array(await workbook(state,docs)),'summary.csv':strToU8(csv(summaryRows(state,docs))),'issues.csv':strToU8(csv(issueRows(state,docs)))};const manifest=[];
 for(const d of docs){const {data,hash}=await original(d),path=archivePath(state,d);files[path]=data;manifest.push({id:d.id,filename:d.filename,path,sha256:hash,bytes:data.length});}
 files['manifest.json']=strToU8(JSON.stringify(manifest,null,2));files['README.txt']=strToU8('InvoiceGuard originals archive. Original bytes are unchanged; verify SHA-256 against manifest.json. Excel/CSV are metadata reports (not containers for original files). Open CSV using Import > Text/CSV with tax IDs and invoice numbers as text to retain leading zeros and long IDs. Excluded originals are retained for audit. Use full Backup for a restorable workspace.');download(zipSync(files,{level:5}),'InvoiceGuard-archive.zip','application/zip');}
export async function exportBackup(state){const {zipSync,strToU8}=await import('fflate');const documents=[],files={};for(const d of state.documents){const {data,hash}=await original(d);files['files/'+safePath(d.id)]=data;documents.push({...d,hash});}files['workspace.json']=strToU8(JSON.stringify({...state,documents},null,2));download(zipSync(files,{level:5}),'InvoiceGuard-backup.zip','application/zip');}
export async function importBackup(file){if(file.size>150*1024*1024)throw new Error('Backup exceeds 150 MB.');const {unzipSync,strFromU8}=await import('fflate');let expanded=0;const files=unzipSync(new Uint8Array(await file.arrayBuffer()),{filter:entry=>{expanded+=entry.originalSize;if(expanded>300*1024*1024)throw new Error('Backup expands beyond 300 MB.');return true;}});if(!files['workspace.json'])throw new Error('This is not an InvoiceGuard backup.');const state=assertBackup(JSON.parse(strFromU8(files['workspace.json']))),originals=[];
 for(const d of state.documents){const data=files['files/'+safePath(d.id)];if(!data)throw new Error('Backup original missing: '+d.filename);const hash=await sha256(data);if(d.hash&&!(d.sample&&/^sample-/.test(d.hash))&&d.hash!==hash)throw new Error('Backup checksum mismatch: '+d.filename);d.hash=hash;originals.push([d.id,new Blob([data],{type:d.mimeType||'application/octet-stream'})]);}await replaceWorkspace(state,originals);return state;}
