 const [page,setPage]=useState('invoices'),[companyId,setCompanyId]=useState('all'),[batchId,setBatchId]=useState('all'),[filter,setFilter]=useState('all'),[search,setSearch]=useState(''),[modal,setModal]=useState(null),[toast,setToast]=useState(''),[fatal,setFatal]=useState(''),[busy,setBusy]=useState(false),[progress,setProgress]=useState(''),[mobileNav,setMobileNav]=useState(false),[exportOpen,setExportOpen]=useState(false);
 const [uploadCompany,setUploadCompany]=useState(''),[uploadBatch,setUploadBatch]=useState(''); const uploadRef=useRef(),restoreRef=useRef(),stateRef=useRef(null),busyRef=useRef(false);
 const t=(en,zh)=>lang==='zh'?zh:en;const label=arr=>arr?.[lang==='zh'?1:0]||'';
 useEffect(()=>{loadWorkspace().then(s=>{stateRef.current=s||emptyWorkspace();setState(stateRef.current);}).catch(e=>setFatal(e.message));},[]);
 useEffect(()=>{document.documentElement.lang=lang==='zh'?'zh-CN':'en';try{localStorage.setItem('invoiceguard-language',lang);}catch{/* IndexedDB availability is reported separately. */}},[lang]);
 useEffect(()=>{if(toast){const timer=setTimeout(()=>setToast(''),7000);return()=>clearTimeout(timer);}},[toast]);
 async function commit(next){await saveWorkspace(next);stateRef.current=next;setState(next);}
 async function run(fn){if(busyRef.current)return;busyRef.current=true;setBusy(true);try{await fn();}catch(e){setToast(t('Action failed: ','操作失败：')+e.message);}finally{busyRef.current=false;setBusy(false);setProgress('');}}
 const analyses=useMemo(()=>new Map((state?.documents||[]).map(d=>{const issues=validate(d,state.companies.find(c=>c.id===d.companyId),state.documents);return[d.id,{issues,status:statusOf(d,issues)}];})),[state]);
 if(fatal)return <div className="loading"><ShieldCheck/><h1>InvoiceGuard</h1><p>Local storage is unavailable: {fatal}</p><p>Enable browser storage and reload. No documents were saved.</p></div>;
 if(!state)return <div className="loading"><ShieldCheck/><p>Opening your local workspace…</p></div>;
 const scoped=state.documents.filter(d=>(companyId==='all'||d.companyId===companyId)&&(batchId==='all'||d.batchId===batchId));
 const visible=scoped.filter(d=>(filter==='all'||analyses.get(d.id).status===filter)&&[d.vendor,d.filename,d.invoiceNumber,d.buyer].some(v=>String(v||'').toLowerCase().includes(search.toLowerCase())));
 const sum=totals(scoped),ready=scoped.filter(d=>analyses.get(d.id).status==='ready').length,flagged=scoped.filter(d=>analyses.get(d.id).status==='flagged').length,review=scoped.filter(d=>analyses.get(d.id).status==='review').length;
