 function openUpload(){const c=companyId==='all'?companies[0]?.id:companyId;if(!c){setModal({kind:'company'});setToast(t('Add your company first, then create a batch.','请先添加公司，再创建报销批次。'));return;}setUploadCompany(c);setUploadBatch(state.batches.find(b=>b.id===batchId&&b.status==='draft')?.id||state.batches.find(b=>b.companyId===c&&b.status==='draft')?.id||'');setModal({kind:'upload'});}
 async function addSamples(){await run(async()=>{if(state.companies.some(c=>c.sample)){setToast(t('Sample workspace is already loaded.','示例数据已加载。'));return;}const sample=sampleWorkspace();for(const d of sample.documents){const file=new Blob([d.rawText],{type:'application/xml'});d.hash=await sha256(await file.arrayBuffer());await saveFile(d.id,file);}await commit({...state,companies:[...state.companies,...sample.companies],batches:[...state.batches,...sample.batches],documents:[...state.documents,...sample.documents]});setCompanyId('company-us');setBatchId('batch-nov');setPage('invoices');setToast(t('Sample data loaded. All names and documents are fictional.','示例已加载，所有名称与单据均为虚构。'));});}
 async function processFiles(fileList){const files=[...fileList];if(!files.length)return;if(!uploadBatch){setToast(t('Create or select a draft batch first.','请先创建或选择草稿批次。'));return;}if(files.length>100){setToast(t('Upload up to 100 files at a time.','每次最多上传100个文件。'));return;}
  await run(async()=>{const {extractFile}=await import('./extract');let failed=0,added=0;const company=companies.find(c=>c.id===uploadCompany);
   for(const [index,file]of files.entries()){
    setProgress(`${index+1}/${files.length} · ${file.name}`);
    if(file.size>25*1024*1024||! /\.(pdf|xml|png|jpe?g|webp|bmp)$/i.test(file.name)){failed++;continue;}
    const id=crypto.randomUUID();let extracted;
    try{extracted=await extractFile(file,company.country,(step,pct)=>setProgress(`${index+1}/${files.length} · ${file.name} · ${step} ${pct}%`));}catch(e){failed++;extracted={country:company.country,currency:company.country==='CN'?'CNY':'USD',documentType:'other',category:'other',processingError:String(e.message||e),hash:await sha256(await file.arrayBuffer()),rawText:'',reviewed:false};}
    const doc={id,filename:file.name,mimeType:file.type,companyId:uploadCompany,batchId:uploadBatch,createdAt:new Date().toISOString(),...extracted};
    const next={...stateRef.current,documents:[...stateRef.current.documents,doc]};await saveDocument(next,id,file);stateRef.current=next;setState(next);added++;
   }setModal(null);setPage('invoices');setCompanyId(uploadCompany);setBatchId(uploadBatch);setFilter('all');setToast(t(`${added} files saved. ${failed} failed or were skipped. Review extracted fields before approval.`,`已保存${added}个文件，${failed}个失败或被跳过。请核对提取字段。`));
  });
 }
