 async function batchAction(batch,next){await run(async()=>{const docs=state.documents.filter(d=>d.batchId===batch.id&&!d.excluded);if(next!=='draft'&&(!docs.length||docs.some(d=>analyses.get(d.id).status!=='ready')))throw new Error(t('All included documents must be reviewed and free of blocking issues.','所有纳入报销的单据须完成审核并无阻断问题。'));await commit({...state,batches:state.batches.map(b=>b.id===batch.id?{...b,status:next,updatedAt:new Date().toISOString()}:b)});setToast(t('Batch status updated.','批次状态已更新。'));});}
 const editorDoc=modal?.kind==='edit'?state.documents.find(d=>d.id===modal.id):null;
